-- #226 파트너 활동 정보(활동 지역·요일별 시간·이동수단·보행 보조·선호 병원) 저장과 고객 공개 v2.
-- 처리방침 제1조 2호(파트너 매칭) — 매칭은 제5조 단계 1 제공 정보와 파트너 설정을 서버에서 비교만 한다.
-- 처리방침 제16조 ③ — 공개 항목이 늘어나므로 활동 정보는 고지 v2에 동의한 파트너만 공개한다.
-- 이용약관 제13조 ③④ — 서비스 제공시간 매일 07:00~19:00. 활동 시간은 이 범위 안에서만 받는다.
-- 매뉴얼 2장 — 파트너는 운전하지 않는다. 이동수단은 예약의 4종(reservations_transport_check)과 같다.
-- 고객 공개는 partner_activity_release(기본 false)를 고지 v2 배포 후 켤 때만 열린다.

-- 활동 지역: 법정동 계층 (시·도 → 시·군·구 → 일반구 → 읍·면·동, 리 제외).
-- 원본: 국토교통부_전국 법정동_20260630 (공공데이터포털 15063424). 전남광주통합특별시·인천 서해구 등 반영.
-- 생성: node scripts/build-activity-regions.mjs <법정동.csv>. 개편 시 새 CSV로 다시 생성한다.
-- 상위 지역 선택은 하위 전체를 뜻한다. ancestors 로 포함 관계를 판정한다(코드 앞자리로는 안 됨).
create table public.partner_activity_regions (
  code text primary key check (code ~ '^[0-9]{10}$'),
  level smallint not null check (level between 1 and 4),
  parent_code text references public.partner_activity_regions(code),
  name text not null,
  full_name text not null,
  ancestors text[] not null,
  sort_order integer not null unique,
  check ((level = 1) = (parent_code is null))
);
create index idx_partner_activity_regions_parent on public.partner_activity_regions(parent_code, sort_order);
